      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction established that controllable large-scale quantum computation is physically possible despite decoherence.",
        "attribution": "Shor, Steane and Kitaev made distinct foundational contributions to codes, fault tolerance and topological protection.",
        "maturity": "The theory has become the central framework for experimental quantum-computing programmes, with increasingly persuasive demonstrations.",
        "uncertainties": [
          "A fully fault-tolerant logical quantum computer has not yet been realized."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions made quantum information a controllable laboratory reality and remain a benchmark quantum platform.",
        "attribution": "Cirac and Zoller supplied decisive concepts and Blatt led landmark experimental realization and development.",
        "maturity": "The platform has delivered reproducible high-fidelity control, entanglement and programmable processors across laboratories.",
        "uncertainties": [
          "The distinction between foundational trapped-ion work and broader quantum-information recognition requires careful delimitation."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement by reaching extraordinary accuracy with many controlled atoms.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept, while Ye made defining experimental advances and independent realization.",
        "maturity": "The method is robustly reproduced, technologically mature and already enables new tests of fundamental physics.",
        "uncertainties": [
          "The proper boundary between clock invention and the wider precision-metrology community needs assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade converted neutral atoms into a powerful programmable many-body quantum system.",
        "attribution": "Saffman developed crucial blockade and gate ideas; Lukin and Browaeys delivered seminal experimental control and scalable arrays.",
        "maturity": "Large coherent arrays and quantum-simulation results are now reproduced broadly and are advancing rapidly.",
        "uncertainties": [
          "The field remains fast-moving, and the ultimate computing advantage is not yet established."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological phases revealed a profound operational aspect of quantum mechanics with consequences across physics.",
        "attribution": "Aharonov introduced the experimentally decisive electromagnetic-potential effect; Berry established the general adiabatic geometric phase.",
        "maturity": "Both effects have extensive, precise experimental support and enduring conceptual influence.",
        "uncertainties": [
          "The conceptual and historical relation between the two effects must be framed without overstating their identity."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made individual superconducting artificial atoms coherently addressable through microwave quantum optics.",
        "attribution": "Blais provided central theory, while Wallraff and Schoelkopf established the defining experimental architecture.",
        "maturity": "It is a reproducible foundation of modern superconducting quantum science and technology.",
        "uncertainties": [
          "The proximity to recent recognition of superconducting circuits and possible overlap in attribution deserve careful consideration."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought engineered mechanical objects into the quantum regime and created a new quantum-optical interface.",
        "attribution": "The named researchers made complementary seminal contributions to experimental platforms, control and quantum demonstrations.",
        "maturity": "Ground-state cooling, quantum transduction and nonclassical mechanical control are established in multiple laboratories.",
        "uncertainties": [
          "Attribution among the many pioneers of optomechanics is difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent optical control of individual nitrogen-vacancy spins created a uniquely useful solid-state quantum sensor and qubit.",
        "attribution": "Jelezko and Wrachtrup pioneered the key single-defect measurements; Lukin made influential advances in coherent control and applications.",
        "maturity": "The techniques are widely replicated and have become a durable platform for quantum sensing.",
        "uncertainties": [
          "The discovery spans several related solid-state-spin advances, making a sharply bounded citation challenging."
        ]
      }
    }
  ]
